-- 0001_initial_schema.sql
-- Shared Bill Splitter — Cloudflare D1 / SQLite
--
-- IDs are generated by the API (UUIDs). Human-readable codes are separate
-- references and must never be used as foreign keys.

CREATE TABLE users (
  id TEXT PRIMARY KEY NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);

CREATE TABLE homes (
  id TEXT PRIMARY KEY NOT NULL,
  home_code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE members (
  id TEXT PRIMARY KEY NOT NULL,
  home_id TEXT NOT NULL,
  user_id TEXT,
  membership_code TEXT NOT NULL UNIQUE,
  member_number INTEGER NOT NULL CHECK (member_number > 0),
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'departed')),
  joined_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  departed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

  -- A member number is never reused within a home, even after departure.
  UNIQUE (home_id, member_number),

  -- Composite parent key used to ensure shares/creators belong to the same home.
  UNIQUE (id, home_id),

  FOREIGN KEY (home_id) REFERENCES homes(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT,

  CHECK (
    (status = 'active' AND departed_at IS NULL)
    OR
    (status = 'departed' AND departed_at IS NOT NULL)
  )
);

-- One account may have only one active membership in a given home.
-- A departed user can rejoin later with a new membership row and member_number.
CREATE UNIQUE INDEX idx_members_one_active_user_per_home
  ON members(home_id, user_id)
  WHERE user_id IS NOT NULL AND status = 'active';

CREATE INDEX idx_members_home_order
  ON members(home_id, status, member_number);

CREATE INDEX idx_members_user
  ON members(user_id);

CREATE TABLE bills (
  id TEXT PRIMARY KEY NOT NULL,
  home_id TEXT NOT NULL,
  bill_number TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL CHECK (length(trim(title)) > 0),
  total_cents INTEGER NOT NULL CHECK (total_cents > 0),
  currency_code TEXT NOT NULL DEFAULT 'USD'
    CHECK (length(currency_code) = 3 AND currency_code = upper(currency_code)),
  created_by_member_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

  UNIQUE (id, home_id),

  FOREIGN KEY (home_id) REFERENCES homes(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by_member_id, home_id)
    REFERENCES members(id, home_id) ON DELETE RESTRICT
);

CREATE INDEX idx_bills_home_created
  ON bills(home_id, created_at DESC);

CREATE TABLE shares (
  id TEXT PRIMARY KEY NOT NULL,
  bill_id TEXT NOT NULL,
  home_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
  paid_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

  -- A member receives at most one share for a particular bill.
  UNIQUE (bill_id, member_id),

  -- Parent key for payment amount integrity.
  UNIQUE (id, amount_cents),

  FOREIGN KEY (bill_id, home_id)
    REFERENCES bills(id, home_id) ON DELETE RESTRICT,
  FOREIGN KEY (member_id, home_id)
    REFERENCES members(id, home_id) ON DELETE RESTRICT
);

CREATE INDEX idx_shares_bill
  ON shares(bill_id);

CREATE INDEX idx_shares_member_unpaid
  ON shares(member_id, paid_at);

CREATE TABLE payments (
  id TEXT PRIMARY KEY NOT NULL,
  payment_reference TEXT NOT NULL UNIQUE,
  share_id TEXT NOT NULL UNIQUE,
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
  idempotency_key TEXT NOT NULL UNIQUE,
  provider TEXT,
  provider_transaction_id TEXT,
  paid_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

  -- The payment amount must equal the immutable share amount.
  FOREIGN KEY (share_id, amount_cents)
    REFERENCES shares(id, amount_cents) ON DELETE RESTRICT,

  -- Provider transaction IDs are unique within a provider.
  UNIQUE (provider, provider_transaction_id)
);

CREATE INDEX idx_payments_paid_at
  ON payments(paid_at);

